            //BON MILLITAIRE
            public function printbon($ckey, $code_b)
            {
                  $this->entreprise = $this->m_entreprises->get_key($ckey);
                  $reponse = $this->m_bon_millitaire->getb($this->entreprise->ekey, $code_b);
                  $pdf = new TCPDF(PDF_PAGE_ORIENTATION, PDF_UNIT, PDF_PAGE_FORMAT, true, 'UTF-8', false);
              
                  $dat = explode("-", $reponse->date_bon);
                  $day = $dat[2]. '-'. $dat[1]. '-' .$dat[0];
                  // set document information
                  $pdf->setCreator(PDF_CREATOR);
                  $pdf->SetAuthor('NET SOLUTIONS');
                  $pdf->SetTitle('TICKET-' . $reponse->nom_client);
                  $pdf->SetSubject('RESERVATIONS');
                  $pdf->SetKeywords('--');
                  
                  $pdf->setPrintHeader(false);
                  $pdf->setPrintFooter(false);
                  
                  // set default monospaced font
                  $pdf->SetDefaultMonospacedFont(PDF_FONT_MONOSPACED);
                  
                  // set margins
                  $pdf->SetMargins(PDF_MARGIN_LEFT, PDF_MARGIN_TOP, PDF_MARGIN_RIGHT);
                  
                  
                  // set auto page breaks
                  $pdf->SetAutoPageBreak(FALSE);
                  
                  // set image scale factor
                  $pdf->setImageScale(PDF_IMAGE_SCALE_RATIO);
                  
                  // add a page
                  $pdf->AddPage('P', 'A4');
                  
                  //----------------------------------------------------------------------------
                  
                  $pdf->SetFont('Helvetica', '', 10);
                  $pdf->Image($reponse->logo, 50, 0, 35, 25, '', '', '', true, 100, 'L');
                  $pdf->SetFont('Helvetica', 'I', 10);
                  $pdf->MultiCell(80, 0, ''.$reponse->contact_national, 0, 'R', 0, 0, 25, 5, true);
                  $pdf->MultiCell(60, 0, 'BON MILLITAIRE', 0, 'C', 0, 0, 40, 30, true);
                  $pdf->MultiCell(60, 0, 'TICKET NON REMBOURSABLE', 1, 'c', 0, 0, 45, 35, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(40, 0, 'CODE DU BON : ', 0, 'L', 0, 0, 10, 44, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(70, 0, '' . $reponse->bonsecondid, 0, 'L', 0, 0, 35, 44, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(40, 0, 'N° DU BON : ', 0, 'L', 0, 0, 10, 49, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(70, 0, '' . $reponse->code_bon, 0, 'L', 0, 0, 30, 49, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(35, 0, 'NOM : ', 0, 'L', 0, 0, 10, 54, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(35, 0, '' . $reponse->nom_client, 0, 'L', 0, 0, 20, 54, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(30, 0, 'PRENOM : ', 0, 'L', 0, 0, 10, 59, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(70, 0, '' . $reponse->prenom_client, 0, 'L', 0, 0, 27, 59, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(35, 0, 'DEPART : ', 0, 'L', 0, 0, 10, 64, true);
                  $pdf->MultiCell(60, 0, 'DESTINATION : ', 0, 'L', 0, 0, 50, 64, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(35, 0, '' . $reponse->nom_gaep, 0, 'L', 0, 0, 27, 64, true);
                  $pdf->MultiCell(70, 0, '' . $reponse->nom_gadest, 0, 'L', 0, 0, 80, 64, true);
                  $pdf->SetFont('Helvetica', 'I', 9);
                  $pdf->MultiCell(50, 0, $reponse->nom_gaep.', le : ', 0, 'c', 0, 0, 35, 74, true);
                  $pdf->SetFont('Helvetica', 'BI', 9);
                  $pdf->MultiCell(75, 0, '' . $day, 0, 'c', 0, 0, 60, 74, true);
                  /* DECLINAISON DE PERTE */
                  $pdf->setFont('Helvetica', 'BI', 6);
                  $pdf->MultiCell(125, 0, $reponse->nom_compagnie . ' décline toute responsabilité en cas de perte ou de vol de billet et de bagages même payés.', 0, 'C', 0, 0, 5, 79, true);
                  /* MISE EN GARE ET RAPPEL */
                  $pdf->setFont('Helvetica', 'I', 6);
                  $pdf->MultiCell(125, 0, 'Suivez et surveillez bien vos bagages', 0, 'C', 0, 0, 5, 83, true);
                  /* BON VOYAGE */
                  $pdf->setFont('Helvetica', '', 6);
                  $pdf->MultiCell(60, 0, "BON VOYAGE AVEC", 0, 'R', 0, 0, 5, 88, true);
                  $pdf->setFont('Helvetica', 'BI', 6);
                  $pdf->MultiCell(60, 0, "{$reponse->nom_compagnie}", 0, 'L', 0, 0, 65, 88, true);
                  // Clean any content of the output buffer
                  ob_end_clean();
                  //Close and output PDF document
                  
                  $pdf->Output($reponse->code_bon . '', 'I');
                  //============================================================+
                  // END OF FILEgit
                  //============================================================+
            }



