            //cv

            public function printcv($ckey, $code_cv)
            {
                  $this->entreprise = $this->m_entreprises->get_key($ckey);
                  $reponse = $this->m_carte_voyage->gets($code_cv);
                  $pdf = new TCPDF(PDF_PAGE_ORIENTATION, PDF_UNIT, PDF_PAGE_FORMAT, true, 'UTF-8', false);
              
                  $dat = explode("-", $reponse->date_valide);
                  $day = $dat[2]. '-'. $dat[1]. '-' .$dat[0];

                  $dat1 = explode("-", $reponse->date_expire);
                  $day1 = $dat1[2]. '-'. $dat1[1]. '-' .$dat1[0];

                  $dat2 = explode("-", $reponse->datenaiss);
                  $dnaiss = $dat2[2]. '-'. $dat2[1]. '-' .$dat2[0];
                  
                  // set document information
                  $pdf->setCreator(PDF_CREATOR);
                  $pdf->SetAuthor('NET SOLUTIONS');
                  $pdf->SetTitle('TICKET-' . $reponse->nom_client);
                  $pdf->SetSubject('RESERVATIONS');
                  $pdf->SetKeywords('--');
                  
                  $pdf->setPrintHeader(false);
                  $pdf->setPrintFooter(false);
                  
                  // set default monospaced font
                  $pdf->SetDefaultMonospacedFont(PDF_FONT_MONOSPACED);
                  
                  // set margins
                  $pdf->SetMargins(PDF_MARGIN_LEFT, PDF_MARGIN_TOP, PDF_MARGIN_RIGHT);
                  
                  
                  // set auto page breaks
                  $pdf->SetAutoPageBreak(FALSE);
                  
                  // set image scale factor
                  $pdf->setImageScale(PDF_IMAGE_SCALE_RATIO);
                  
                  // add a page
                  $pdf->AddPage('P', 'A4');
                  
                  //----------------------------------------------------------------------------
                  
                  $pdf->SetFont('Helvetica', '', 10);
                  $pdf->Image($reponse->imgcomp, 10, 5, 35, 20, '', '', '', true, 100, 'L');
                  $pdf->Image($reponse->imageperso, 50, 10, 40, 50, '', '', '', true, 100, 'C');
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(50, 0, 'CARTE DE VOYAGE ', 0, 'L', 0, 0, 15, 29, true);
                  $pdf->SetTextColor(255, 0, 0);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(80, 0, '' .$reponse->id_carte, 0, 'L', 0, 0, 48, 29, true);
                  $pdf->SetTextColor(0, 0, 0);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(40, 0, 'Nom : ', 0, 'L', 0, 0, 10, 40, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(70, 0, '' . $reponse->nom_client, 0, 'L', 0, 0, 27, 40, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(40, 0, 'Prénom : ', 0, 'L', 0, 0, 10, 45, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(70, 0, '' . $reponse->prenom_client, 0, 'L', 0, 0, 27, 45, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(35, 0, 'Né le ', 0, 'L', 0, 0, 10, 50, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(35, 0, '' . $dnaiss.'  '. $reponse->lieunaiss, 0, 'L', 0, 0, 20, 50, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(30, 0, 'Adresse : ', 0, 'L', 0, 0, 10, 55, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(70, 0, '' .$reponse->profession.'   ' . $reponse->contact_client, 0, 'L', 0, 0, 27, 55, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(35, 0, 'valable', 0, 'L', 0, 0, 10, 60, true);
                  $pdf->MultiCell(60, 0, 'Validité : ', 0, 'L', 0, 0, 10, 65, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(70, 0, 'sur toutes les lignes '.$reponse->valable, 0, 'L', 0, 0, 27, 60, true);
                  $pdf->MultiCell(70, 0, 'Du'.'  ' . $day.'  '. 'au' .'  '.$day1, 0, 'L', 0, 0, 27, 65, true);
                  $pdf->SetFont('Helvetica', '', 9);
                  $pdf->MultiCell(50, 0, 'Durée : ', 0, 'c', 0, 0, 10, 70, true);
                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(50, 0, ''.$reponse->dureevalid, 0, 'C', 0, 0, 10, 70, true);

                  $pdf->SetFont('Helvetica', 'B', 9);
                  $pdf->MultiCell(75, 0, 'Banfora le, '.utf8_encode(strftime("%d %b %G", now())), 0, 'c', 0, 0, 10, 75, true);
                  // Clean any content of the output buffer
                  ob_end_clean();
                  //Close and output PDF document
                  
                  $pdf->Output($reponse->id_carte . '', 'I');
                  //============================================================+
                  // END OF FILEgit
                  //============================================================+
            }
            //print A4 ticket aller
            public function printpdf($ckey, $code_id, $hr, $idsog)
            {
                  $this->entreprise = $this->m_entreprises->get_key($ckey);
                  
                  if ($this->session->agent->userole === '1' OR $this->session->agent->userole === '2'){
                         $reponse = $this->m_passager->getad($this->entreprise->ekey, $code_id, $hr);
                  }else
                  {
                        $reponse = $this->m_passager->get($this->entreprise->ekey, $code_id, $hr);
                  }
                        $ressougare = $this->m_gare_depart->getgar($this->entreprise->id_entreprise, $reponse->code_gaexp, $reponse->departclient_idgare, $reponse->ident_ligne);
                        if($ressougare->possitiongare === 'Maintenant'){

                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                              $heures = sprintf("%02d:%02d", $heur, $secondes);
                              //$heures = $heur.':'.$secondes;
                        }

                        if($ressougare->possitiongare === 'Avant'){
                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] - $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                                    
                              //$heures = $heur.':'.$secondes;
                              $heures = sprintf("%02d:%02d", $heur, $secondes);
                        }

                        if($ressougare->possitiongare === 'Apres'){
                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                              $heures = sprintf("%02d:%02d", $heur, $secondes);      
                              //$heures = $heur.':'.$secondes;

                        }
                              
                        
                        $nom = $reponse->code_progr;
                        $nge = substr($nom, 6, 6);

                        $dat = explode("-", $reponse->date_progr);
                        $day = $dat[2]. '-'. $dat[1]. '-' .$dat[0];
                        $pdf = new TCPDF(PDF_PAGE_ORIENTATION, PDF_UNIT, PDF_PAGE_FORMAT, true, 'UTF-8', false);
                        
                        // set document information
                        $pdf->setCreator(PDF_CREATOR);
                        $pdf->SetAuthor('NET SOLUTIONS');
                        $pdf->SetTitle('TICKET-' . $reponse->nom_client);
                        $pdf->SetSubject('RESERVATIONS');
                        $pdf->SetKeywords('--');
                        //remove default header/footer
                        $pdf->setPrintHeader(false);
                        $pdf->setPrintFooter(false);
                        
                        // set default monospaced font
                        $pdf->SetDefaultMonospacedFont(PDF_FONT_MONOSPACED);
                        
                        // set margins
                        $pdf->SetMargins(PDF_MARGIN_LEFT, PDF_MARGIN_TOP, PDF_MARGIN_RIGHT);
                        
                        
                        // set auto page breaks
                        $pdf->SetAutoPageBreak(FALSE);
                        
                        // set image scale factor
                        $pdf->setImageScale(PDF_IMAGE_SCALE_RATIO);
                        
                        // add a page
                        $pdf->AddPage('P', 'A4');
                        
                        //----------------------------------------------------------------------------
                        
                        // GROUPE DE GAUCHE
                        $pdf->SetFont('Courier', 'B', 9);
                        
                        $pdf->MultiCell(60, 0, '' . $reponse->code_ticket, 0, 'L', 0, 0, 4, 20, true);
                        
                        /* AXE ET PRIX */
                        $pdf->SetFont('Courier', 'B', 9);
                        $pdf->MultiCell(40, 0, '' . $reponse->nom_ligne, 0, 'L', 0, 0, 4, 25, true);
                  
                        /* DATE ET HEURE */
                        $pdf->MultiCell(50, 0, '' .$ressougare->nomsousgare, 0, 'L', 0, 0, 4, 30, true);
                        $pdf->MultiCell(30, 0, '' .$day, 0, 'L', 0, 0, 5, 35, true);
                        $pdf->MultiCell(35, 0, '' . $heures, 0, 'L', 0, 0, 25, 35, true);
                        $pdf->MultiCell(15, 0, '' . str_pad($reponse->num_siege_categorie, 2, "0", STR_PAD_LEFT), 0, 'L', 0, 0, 4, 40, true);
                        $pdf->SetFont('courier', 'B', 10);
                        $pdf->MultiCell(60, 0, '' .$reponse->quart, 0, 'L', 0, 0, 15, 40, true);
                        /* NOM */$pdf->SetFont('Courier', '', 8);
                        $pdf->MultiCell(70, 0, '' . $reponse->nom_client, 0, 'L', 0, 0, 4, 45, true);
                        /* PRENOM */
                        $pdf->MultiCell(70, 0, '' . $reponse->prenom_client, 0, 'L', 0, 0, 4, 50, true);
                        /* TELEPHONE */
                        $pdf->MultiCell(75, 0, '' . $reponse->contact_client, 0, 'L', 0, 0, 4, 55, true);
                        
