                  $pdf->MultiCell(70, 0, '' . $reponse->nom_client, 0, 'L', 0, 0, 4, 40, true);
                  /* PRENOM */
                  $pdf->MultiCell(70, 0, '' . $reponse->prenom_client, 0, 'L', 0, 0, 4, 45, true);
                  /* TELEPHONE */
                  $pdf->MultiCell(75, 0, '' . $reponse->contact_client, 0, 'L', 0, 0, 4, 50, true);
                  
                  $pdf->SetFont('Courier', '', 10);
                  $pdf->MultiCell(35, 0, '' . number_format($reponse->prix, 0, '', ' ').' '. 'HT', 0, 'L', 0, 0, 4, 55, true);
                  
                  $pdf->setFont('Helvetica', 'BI', 8);
