            public function liste($ckey)
            {
                  $cdp = $this->input->post('categoriebus');
                  $imat = $this->input->post('bus');
                  $cd = $this->input->post('chauffeur');
                  $cprg = $this->input->post('progra');
                  $cv = $this->input->post('convoi');
                  $da = $this->input->post('dateencour');
                  $ligne = $this->input->post('ligne');
                  $gid = $this->input->post('garedp');
                  $toute = $this->input->post('touteligne');
                  //identifiant l'heure dans la table ligne heure
                  $ligne_lh = strpos($this->input->post('ligne'), '-');
                  
                  $ligneh = substr($this->input->post('ligne'), 0, $ligne_lh);
                  $lignelhre = substr($this->input->post('ligne'), $ligne_lh + 1, strlen($this->input->post('ligne')));
                  
                  $post_h = strpos($this->input->post('heurex'), '/');
                  
                  $h = substr($this->input->post('heurex'), 0, $post_h);
                  $hre = substr($this->input->post('heurex'), $post_h + 1, strlen($this->input->post('heurex')));
                  
                  $post_heure = strpos($this->input->post('progra'), '/');
                  
                  $sub_heure = substr($this->input->post('progra'), 0, $post_heure);

                  $dprog = substr($this->input->post('progra'), $post_heure + 1, strlen($this->input->post('progra')));
                  $itineraire = $this->db->query("SELECT l.nom_ligne, l.ident_ligne FROM lignes l WHERE l.ident_ligne = '$ligne'")->row();
                  
                  
                  $nom = $cdp;
