            public function printpdftransit($ckey, $code_id, $hr, $co, $lr, $idsog)
            {
                  $this->entreprise = $this->m_entreprises->get_key($ckey);
                  $reponse = $this->m_passager->get($this->entreprise->ekey, $code_id, $hr);
                  $reponsetrans = $this->m_passager->get($this->entreprise->ekey, $co, $lr);

                  $ressougare = $this->m_gare_depart->getgar($this->entreprise->id_entreprise, $reponse->code_gaexp, $reponse->departclient_idgare, $reponse->ident_ligne);
                  $ressougaretra = $this->m_gare_depart->getgar($this->entreprise->id_entreprise, $reponsetrans->code_gaexp, $reponsetrans->departclient_idgare, $reponsetrans->ident_ligne);

                  if($ressougare->possitiongare === 'Maintenant'){

                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                              $heures = sprintf("%02d:%02d", $heur, $secondes);
                        }

                        if($ressougare->possitiongare === 'Avant'){
                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                              $heures = sprintf("%02d:%02d", $heur, $secondes);                   
                        }

                        if($ressougare->possitiongare === 'Apres'){
                              $g = explode(":", $reponse->heure);
                              $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                              $heur = ($gt / 60); 
                              $secondes = round($gt % 60);
                              $heures = sprintf("%02d:%02d", $heur, $secondes); //$heures = $heur.':'.$secondes;

                        }
                        if($ressougaretra->possitiongare === 'Maintenant'){

                              $g1 = explode(":", $reponsetrans->heure);
                              $gt1 = (($g1[0] * 60) + $g1[1] + $ressougaretra->minutetemps); 
                              $heur1 = ($gt1 / 60); 
                              $secondes1 = round($gt1 % 60);
                              $heures1 = sprintf("%02d:%02d", $heur1, $secondes1);
                        }

                        if($ressougaretra->possitiongare === 'Avant'){
                              $g1 = explode(":", $reponsetrans->heure);
                              $gt1 = (($g1[0] * 60) + $g1[1] + $ressougaretra->minutetemps); 
                              $heur1 = ($gt1 / 60); 
                              $secondes1 = round($gt1 % 60);
                              $heures1 = sprintf("%02d:%02d", $heur1, $secondes1);                   
