            public function printpdftransitarepson($ckey, $code_p, $code_np, $hre, $code_p1, $code_np1, $hre1, $idsog)
            {
                  $this->entreprise = $this->m_entreprises->get_key($ckey);
                  $reponse = $this->m_passager->get($this->entreprise->ekey, $code_p, $hre);
                  $fiche = $this->m_non_passager->getad($this->entreprise->ekey, $code_np);

                  $reponsetrans = $this->m_passager->get($this->entreprise->ekey, $code_p1, $hre1);
                  $fichetrans = $this->m_non_passager->getad($this->entreprise->ekey, $code_np1);

                  $ressougare = $this->m_gare_depart->getgar($this->entreprise->id_entreprise, $reponse->code_gaexp, $reponse->departclient_idgare, $reponse->ident_ligne);
                  $ressougaretra = $this->m_gare_depart->getgar($this->entreprise->id_entreprise, $reponsetrans->code_gaexp, $reponsetrans->departclient_idgare, $reponsetrans->ident_ligne);

                  if($ressougare->possitiongare === 'Maintenant'){

                        $g = explode(":", $reponse->heure);
                        $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
                        $heur = ($gt / 60); 
                        $secondes = round($gt % 60);
                        $heures = sprintf("%02d:%02d", $heur, $secondes);
                  }

                  if($ressougare->possitiongare === 'Avant'){
                        $g = explode(":", $reponse->heure);
                        $gt = (($g[0] * 60) + $g[1] + $ressougare->minutetemps); 
